const b=$json.body||$json;
const requestId=String(b.request_id||('wf128-'+Date.now()));
const dealId=b.deal_id||null,leadId=b.lead_id||null,propertyId=b.property_id||null;
const readinessId=b.buyer_funding_readiness_id||null;
const strategy=String(b.exit_strategy||b.disposition_strategy||'').toLowerCase().replace(/ /g,'_').replace(/-/g,'_');
const buyerId=b.buyer_id||b.assignee_id||null;
const buyerName=b.buyer_name||b.assignee_name||null;
const buyerScore=Number.isFinite(Number(b.buyer_match_score))?Number(b.buyer_match_score):null;
const buyerPrice=Number.isFinite(Number(b.buyer_price))?Number(b.buyer_price):null;
const sellerPrice=Number.isFinite(Number(b.agreed_price||b.purchase_price))?Number(b.agreed_price||b.purchase_price):null;
const assignmentFee=Number.isFinite(Number(b.assignment_fee))?Number(b.assignment_fee):null;
const expectedSpread=Number.isFinite(Number(b.expected_spread))?Number(b.expected_spread):((buyerPrice!==null&&sellerPrice!==null)?buyerPrice-sellerPrice:null);
const fundingStatus=String(b.funding_status||b.double_close_funding_status||'').toLowerCase();
const buyerStatus=String(b.buyer_status||b.assignee_status||'').toLowerCase();
const readinessStatus=String(b.readiness_status||'').toLowerCase();
const dnc=Boolean(b.dnc),missing=[];
if(!dealId)missing.push('deal_id');if(!leadId)missing.push('lead_id');if(!propertyId)missing.push('property_id');if(!readinessId)missing.push('buyer_funding_readiness_id');if(!strategy)missing.push('exit_strategy');
const blockers=[];
if(!['assignment','novation','double_close'].includes(strategy))blockers.push('unsupported_exit_strategy');
if(readinessStatus&&readinessStatus!=='ready')blockers.push('buyer_funding_readiness_not_ready');
if(['assignment','novation','double_close'].includes(strategy)&&!buyerId)blockers.push('buyer_or_assignee_missing');
if(buyerId&&!['ready','selected','confirmed','verified'].includes(buyerStatus))blockers.push('buyer_or_assignee_not_confirmed');
if(buyerId&&buyerScore!==null&&buyerScore<60)blockers.push('buyer_match_score_below_threshold');
if(strategy==='assignment'&&buyerPrice!==null&&sellerPrice!==null&&buyerPrice<=sellerPrice)blockers.push('assignment_economics_non_positive');
if(strategy==='assignment'&&assignmentFee!==null&&assignmentFee<=0)blockers.push('assignment_fee_non_positive');
if(strategy==='double_close'&&!['ready','verified','confirmed','funded','complete'].includes(fundingStatus))blockers.push('double_close_funding_not_ready');
if(strategy==='double_close'&&buyerPrice!==null&&sellerPrice!==null&&buyerPrice<=sellerPrice)blockers.push('double_close_spread_non_positive');
if(strategy==='novation'&&buyerPrice!==null&&sellerPrice!==null&&buyerPrice<=sellerPrice)blockers.push('novation_economics_non_positive');
let status='blocked',nextState='human_review',route='human_review',reason='Exit execution requires review';
if(dnc){status='suppressed';nextState='exit_execution';route='none';reason='DNC suppresses communication only; exit execution state is retained';}
else if(missing.length){status='blocked';nextState='missing_exit_inputs';reason='Required exit execution identity or strategy is missing';}
else if(blockers.length){status='blocked';nextState='exit_blocked';reason='Buyer match, economics, readiness, or funding conditions are unresolved';}
else{status='executable';nextState='exit_execution';route=strategy==='assignment'?'wf-041-assignment-novation-double-close-transaction-tracking':strategy==='novation'?'wf-041-assignment-novation-double-close-transaction-tracking':'wf-041-assignment-novation-double-close-transaction-tracking';reason='Selected exit strategy has a confirmed buyer/assignee and executable economics/readiness';}
const id='exit-execution:'+dealId+':'+requestId+':v1';
const uniqueBlockers=[...new Set(blockers)];
return [{json:{workflow:'WF-128',workflow_version:'1.0',request_id:requestId,exit_execution_id:id,buyer_funding_readiness_id:readinessId,lead_id:leadId,property_id:propertyId,deal_id:dealId,exit_strategy:strategy,buyer_id:buyerId,buyer_name:buyerName,buyer_match_score:buyerScore,buyer_price:buyerPrice,seller_price:sellerPrice,assignment_fee:assignmentFee,expected_spread:expectedSpread,buyer_status:buyerStatus,funding_status:fundingStatus,status,next_state:nextState,route,reason,blockers:uniqueBlockers,economics:{seller_price:sellerPrice,buyer_price:buyerPrice,assignment_fee:assignmentFee,expected_spread:expectedSpread},requirements:['confirmed buyer/assignee match','positive executable exit economics','funding confirmation for double-close','transaction tracking handoff for executable exits'],guardrails:{readiness_required:true,no_invented_buyer_or_funding_evidence:true,non_positive_exit_economics_block_execution:true,buyer_match_score_floor:60,double_close_requires_funding_confirmation:true,dnc_suppresses_communication_not_transaction_state:true},crm_activity:{activity_type:'exit_execution_readiness',subject:'WF-128 exit execution readiness - '+status,lead_id:leadId,property_id:propertyId,deal_id:dealId,external_id:id,external_source:'wholesaling-os-disposition',metadata:{status,next_state,route,reason,exit_strategy,buyer_id:buyerId,buyer_match_score:buyerScore,buyer_price:buyerPrice,seller_price:sellerPrice,assignment_fee:assignmentFee,expected_spread:expectedSpread,funding_status:fundingStatus,blockers:uniqueBlockers}}}}];
